{
  "script": "const email = $vars.emailReceived1.output;
const subject = (email.subject || "").toLowerCase();
const bodyText = (email.body && email.body.content ? email.body.content : "").toLowerCase();
const senderEmail = (email.from && email.from.emailAddress && email.from.emailAddress.address ? email.from.emailAddress.address : "").toLowerCase();

const urgentKeywords = ["urgent", "asap", "critical", "down", "immediately", "emergency"];
const isUrgent = urgentKeywords.some(k => subject.includes(k) || bodyText.includes(k));

// EDIT ME: placeholder VIP allow-list. Add exact VIP email addresses and/or VIP domains here.
const vipAddresses = ["ceo@example.com"];
const vipDomains = ["acmecorp.com"];

const isVip = vipAddresses.includes(senderEmail) || vipDomains.some(d => senderEmail.endsWith("@" + d));

return {
  isUrgent,
  isVip,
  isUrgentAndVip: isUrgent && isVip,
  senderEmail,
  subject: email.subject || "",
  bodySnippet: (email.bodyPreview || "").substring(0, 200)
};"
}

